int n, m, K;
int eu[MAXM], ev[MAXM];
int removed[MAXN]; // removed vertices (in cover)

int solve(int k) {
    // Find an uncovered edge
    int u = -1, v = -1;
    for (int i = 0; i < m; i++) {
        if (!removed[eu[i]] && !removed[ev[i]]) {
            u = eu[i]; v = ev[i];
            break;
        }
    }
    if (u == -1) return 0; // all edges covered
    if (k == 0) return -1; // can't cover more

    // Branch on u
    removed[u] = 1;
    int r1 = solve(k - 1);
    removed[u] = 0;

    // Branch on v
    removed[v] = 1;
    int r2 = solve(k - 1);
    removed[v] = 0;

    if (r1 == -1 && r2 == -1) return -1;
    if (r1 == -1) return 1 + r2;
    if (r2 == -1) return 1 + r1;
    return 1 + (r1 < r2 ? r1 : r2);
}

