    head = (int *)malloc((n1 + 1) * sizeof(int));
    edges = (Edge *)malloc((m + 5) * sizeof(Edge));
    matchR = (int *)malloc((n2 + 1) * sizeof(int));
    vis = (int *)malloc((n2 + 1) * sizeof(int));

    for (int i = 0; i <= n1; i++) head[i] = -1;
    for (int i = 0; i <= n2; i++) {
        matchR[i] = -1;
        vis[i] = 0;
    }

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (u >= 1 && u <= n1 && v >= 1 && v <= n2) {
            add_edge(u, v);
        }
    }

    int max_matching = 0;
    for (int u = 1; u <= n1; u++) {
        vis_token++;
        if (dfs(u)) max_matching++;
    }

    if (max_matching <= k) {
        printf("YES\n%d\n", max_matching);
    } else {
        printf("NO\n");
    }

    free(head);
    free(edges);
    free(matchR);
    free(vis);
    return 0;
}

