#include <bits/stdc++.h>
using namespace std;

/*
This is the classic minimum vertex cover problem on a bipartite graph.

Interpretation:
- Islands are vertices.
- Ocean liners are edges.
- We need to place quarantine stations on some islands so that every liner
  has at least one endpoint with a station.
- We may build at most K stations.
- Need to determine whether possible, and if so the minimum required.

For bipartite graphs, by Konig's theorem:
    minimum vertex cover size = maximum matching size

So:
1) Read bipartite graph.
2) Compute maximum matching with Hopcroft-Karp.
3) Let ans = matching size.
4) If ans <= K => possible, minimum required is ans.
   Otherwise impossible.

Input format assumed:
N M E K
followed by E lines: u v
where
- left part has vertices 1..N
- right part has vertices 1..M
- each edge connects u in left to v in right

Output:
- If impossible: "NO"
- Else: "YES" and the minimum number

If your judge expects a slightly different wording, adjust accordingly.
*/

struct HopcroftKarp {
    int n, m;
    vector<vector<int>> g;
    vector<int> dist, matchL, matchR;

    HopcroftKarp(int n, int m) : n(n), m(m) {
        g.assign(n + 1, {});
        dist.resize(n + 1);
        matchL.assign(n + 1, 0);
        matchR.assign(m + 1, 0);
    }

    void addEdge(int u, int v) {
        g[u].push_back(v);
    }

    bool bfs() {
        queue<int> q;
        for (int u = 1; u <= n; ++u) {
            if (matchL[u] == 0) {
                dist[u] = 0;
                q.push(u);
            } else {
                dist[u] = -1;
            }
        }

        bool found = false;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : g[u]) {
                int w = matchR[v];
                if (w == 0) {
                    found = true;
                } else if (dist[w] == -1) {
                    dist[w] = dist[u] + 1;
                    q.push(w);
                }
            }
        }
        return found;
    }

    bool dfs(int u) {
        for (int v : g[u]) {
            int w = matchR[v];
            if (w == 0 || (dist[w] == dist[u] + 1 && dfs(w))) {
                matchL[u] = v;
                matchR[v] = u;
                return true;
            }
        }
        dist[u] = -1;
        return false;
    }

    int maxMatching() {
        int matching = 0;
        while (bfs()) {
            for (int u = 1; u <= n; ++u) {
                if (matchL[u] == 0 && dfs(u)) {
                    ++matching;
                }
            }
        }
        return matching;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, E, K;
    cin >> N >> M >> E >> K;

    HopcroftKarp hk(N, M);
    for (int i = 0; i < E; ++i) {
        int u, v;
        cin >> u >> v;
        hk.addEdge(u, v);
    }

    int ans = hk.maxMatching();

    if (ans <= K) {
        cout << "YES\n" << ans << "\n";
    } else {
        cout << "NO\n";
    }

    return 0;
}

