def hopcroft_karp(adj, U, pair_U, pair_V, dist):
    INF = 10**9
    q = deque()
    for u in U:
        if pair_U[u] == -1:
            dist[u] = 0
            q.append(u)
        else:
            dist[u] = INF
    dist[-1] = INF
    while q:
        u = q.popleft()
        if dist[u] < dist[-1]:
            for v in adj[u]:
                if dist[pair_V[v]] == INF:
                    dist[pair_V[v]] = dist[u] + 1
                    q.append(pair_V[v])
    return dist[-1] != INF

def dfs(u, adj, pair_U, pair_V, dist):
    if u != -1:
        for v in adj[u]:
            if dist[pair_V[v]] == dist[u] + 1 and dfs(pair_V[v], adj, pair_U, pair_V, dist):
                pair_V[v] = u
                pair_U[u] = v
                return True
        dist[u] = INF
        return False
    return True

