        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    # Bipartite check
    color = [-1] * N
    is_bipartite = True
    left_set = []
    right_set = []
    for i in range(N):
        if color[i] == -1:
            q = deque([i])
            color[i] = 0
            left_set.append(i)
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        if color[v] == 0:
                            left_set.append(v)
                        else:
                            right_set.append(v)
                        q.append(v)
                    elif color[v] == color[u]:
                        is_bipartite = False
                        break
                if not is_bipartite:
                    break
        if not is_bipartite:
            break

    if not is_bipartite:
        print("N")
        return

    # Map left nodes to indices for matching
    left_index = {u: i for i, u in enumerate(left_set)}
    right_index = {v: i for i, v in enumerate(right_set)}

    # Build adjacency for Hopcroft-Karp: from left side to right side
    adj_left = [[] for _ in range(len(left_set))]
    for u in left_set:
        for v in adj[u]:
            if color[v] == 1:  # v is in right set
                adj_left[left_index[u]].append(right_index[v])

    # Hopcroft-Karp expects right side indices 0..R-1
    R = len(right_set)
    pair_U = [-1] * len(left_set)
    pair_V = [-1] * R
    dist = {}

    def bfs():
        q = deque()
        for u in range(len(left_set)):
            if pair_U[u] == -1:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = 10**9
        dist[-1] = 10**9
        while q:
            u = q.popleft()
            if dist[u] < dist[-1]:
                for v in adj_left[u]:
                    if dist[pair_V[v]] == 10**9:
                        dist[pair_V[v]] = dist[u] + 1
                        q.append(pair_V[v])
        return dist[-1] != 10**9

    def dfs(u):
        if u != -1:
            for v in adj_left[u]:
                if dist[pair_V[v]] == dist[u] + 1 and dfs(pair_V[v]):
                    pair_V[v] = u
                    pair_U[u] = v
                    return True
            dist[u] = 10**9
            return False
        return True

    matching = 0
    for u in range(len(left_set)):
        dist[u] = 0
    while bfs():
        for u in range(len(left_set)):
            if pair_U[u] == -1:
                if dfs(u):
                    matching += 1

    if matching <= K:
